create sequence fabrication_stations_SEQ start with 1 increment by 50;
create sequence fabrication_station_employees_SEQ start with 1 increment by 50;
create sequence catering_items_SEQ start with 1 increment by 50;
create sequence catering_item_stores_SEQ start with 1 increment by 50;
create sequence catering_recipes_SEQ start with 1 increment by 50;
create sequence catering_recipe_lines_SEQ start with 1 increment by 50;
create sequence catering_units_SEQ start with 1 increment by 50;
create sequence fabrication_lines_SEQ start with 1 increment by 50;
create sequence fabrication_line_units_SEQ start with 1 increment by 50;
create sequence fabrication_consumptions_SEQ start with 1 increment by 50;
create sequence catering_purchase_needs_SEQ start with 1 increment by 50;
create sequence catering_amendments_SEQ start with 1 increment by 50;
create table fabrication_stations (id bigint not null, version bigint, checksum integer, created_at timestamp(6) not null, updated_at timestamp(6) not null, store_id bigint not null references stores(id), code varchar(40) not null, name varchar(200) not null, building_id bigint references buildings(id), stagingBuffer_id bigint references buffers(id), printer_id bigint references store_printers(id), weekdays varchar(20), closedDates TEXT, opensAt time, closesAt time, dailyMinutes integer, stagingLeadMinutes integer, maxOrderMinutes integer, active boolean not null, primary key (id), constraint uk_station_store_code unique (store_id, code));
create table fabrication_station_employees (id bigint not null, version bigint, checksum integer, created_at timestamp(6) not null, updated_at timestamp(6) not null, station_id bigint not null references fabrication_stations(id), employee_id bigint not null references employees(id), primary key (id), constraint uk_station_employee unique (station_id, employee_id));
create table catering_items (id bigint not null, version bigint, checksum integer, created_at timestamp(6) not null, updated_at timestamp(6) not null, product_id bigint not null unique references products(id), sourcingMode varchar(20) not null, station_id bigint references fabrication_stations(id), shelfLifeHours integer, maxAdvanceHours integer, supplierName varchar(200), supplierLeadDays integer, cancelDispositions varchar(60), fragile boolean not null, active boolean not null, primary key (id));
create table catering_item_stores (id bigint not null, version bigint, checksum integer, created_at timestamp(6) not null, updated_at timestamp(6) not null, item_id bigint not null references catering_items(id), store_id bigint not null references stores(id), sourcingMode varchar(20), station_id bigint references fabrication_stations(id), active boolean not null, primary key (id), constraint uk_item_store unique (item_id, store_id));
create table catering_recipes (id bigint not null, version bigint, checksum integer, created_at timestamp(6) not null, updated_at timestamp(6) not null, item_id bigint not null references catering_items(id), variantId varchar(20) not null, stepId varchar(60), choiceId varchar(60), flavourId varchar(60), laborSeconds integer, revision integer not null, active boolean not null, primary key (id), constraint uk_recipe_key unique (item_id, variantId, stepId, choiceId, flavourId, revision));
create table catering_recipe_lines (id bigint not null, version bigint, checksum integer, created_at timestamp(6) not null, updated_at timestamp(6) not null, recipe_id bigint not null references catering_recipes(id), component_id bigint not null references products(id), quantity numeric(19,6) not null, kind varchar(20) not null, primary key (id));
create table catering_units (id bigint not null, version bigint, checksum integer, created_at timestamp(6) not null, updated_at timestamp(6) not null, order_id bigint not null references orders(id), orderLine_id bigint not null references order_lines(id), lineId varchar(40) not null, ean varchar(40) not null, item_id bigint references catering_items(id), sourcingMode varchar(20) not null, variantId varchar(20), variantLabel varchar(60), configurationKey varchar(64), configuration json, choiceLabels TEXT, allergens TEXT, ingredients TEXT, storage varchar(1000), servingAdvice varchar(1000), quantity numeric(19,6) not null, producedQuantity numeric(19,6) not null, shortQuantity numeric(19,6) not null, availableAt timestamp(6) not null, fulfillmentLine_id bigint references fulfillment_lines(id), state varchar(20) not null, revision integer not null, primary key (id), constraint uk_unit_order_line unique (order_id, lineId));
create table fabrication_lines (id bigint not null, version bigint, checksum integer, created_at timestamp(6) not null, updated_at timestamp(6) not null, order_id bigint not null references handling_orders(id), item_id bigint not null references catering_items(id), variantId varchar(20), configurationKey varchar(64), plannedQuantity numeric(19,6) not null, producedQuantity numeric(19,6) not null, lostQuantity numeric(19,6) not null, shortQuantity numeric(19,6) not null, state varchar(20) not null, producedAt timestamp(6), useBy timestamp(6), lotCode varchar(60), primary key (id));
create table fabrication_line_units (id bigint not null, version bigint, checksum integer, created_at timestamp(6) not null, updated_at timestamp(6) not null, line_id bigint not null references fabrication_lines(id), unit_id bigint not null references catering_units(id), quantity numeric(19,6) not null, producedQuantity numeric(19,6) not null, shortQuantity numeric(19,6) not null, primary key (id));
create table fabrication_consumptions (id bigint not null, version bigint, checksum integer, created_at timestamp(6) not null, updated_at timestamp(6) not null, line_id bigint not null references fabrication_lines(id), component_id bigint not null references products(id), segment_id bigint references stock_segments(id), manufacturerLot_id bigint references manufacturer_lots(id), quantity numeric(19,6) not null, loss boolean not null, primary key (id));
create table catering_purchase_needs (id bigint not null, version bigint, checksum integer, created_at timestamp(6) not null, updated_at timestamp(6) not null, store_id bigint not null references stores(id), unit_id bigint not null references catering_units(id), supplierName varchar(200), quantity numeric(19,6) not null, orderBy timestamp(6), dueAt timestamp(6), state varchar(20) not null, expectedSupply_id bigint references stock_expected_supplies(id), primary key (id));
create table catering_amendments (id bigint not null, version bigint, checksum integer, created_at timestamp(6) not null, updated_at timestamp(6) not null, store_id bigint not null references stores(id), order_id bigint not null references orders(id), principal varchar(100) not null, requestId varchar(100) not null, fingerprint varchar(64), kind varchar(20) not null, payload json, outcome varchar(40), code varchar(60), appliedAt timestamp(6), primary key (id), constraint uk_amendment_principal_request unique (principal, requestId));
alter table products alter column ean set data type varchar(40);
alter table handling_orders add column station_id bigint;
alter table handling_orders add column productionDate date;
alter table handling_orders add column proposalState varchar(20);
alter table handling_orders add column proposedEmployee_id bigint;
alter table handling_orders add column plannedMinutes integer;
alter table handling_orders add constraint fk_fab_order_station foreign key (station_id) references fabrication_stations(id);
alter table handling_orders add constraint fk_fab_order_employee foreign key (proposedEmployee_id) references employees(id);
alter table handling_orders drop constraint ck_handling_order_type_v8;
alter table handling_orders add constraint ck_handling_order_type_v30 check(type in ('ZONE_COLLECTING','PRODUCT_COLLECTING','PACKING','GROUPING','STOCK_PROTECTION','REPLENISHMENT','CANCELLATION_DISPOSITION','INVENTORY','FABRICATION'));
alter table handling_executions drop constraint ck_handling_execution_type_v8;
alter table handling_executions add constraint ck_handling_execution_type_v30 check(execution_type in ('REPLENISHMENT','GROUPING','PICKING','CANCELLATION_DISPOSITION','INVENTORY','FABRICATION'));
alter table orders add column payment_method varchar(20);
alter table orders add column payment_state varchar(20);
alter table orders add column payment_amount numeric(19,2);
alter table orders add column payment_acknowledged_at timestamp(6);
alter table orders add column payment_acknowledged_by varchar(100);
alter table fulfillment_chunks add column catering boolean default false not null;
alter table picking_shortages alter column handlingOrder_id set null;
alter table loaded_totes add column fabrication_execution_id bigint;
alter table picked_items add column fabrication_execution_id bigint;
